CREATE TABLE company (id BIGINT PRIMARY KEY,name VARCHAR(200) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(id) REFERENCES business_record(id));
CREATE TABLE department (id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(id,company_id),FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(company_id) REFERENCES company(id));
CREATE TABLE task (id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,host_dept_id BIGINT NOT NULL,creator_id BIGINT NOT NULL,title VARCHAR(300) NOT NULL,content LONGTEXT NOT NULL,priority VARCHAR(20) NOT NULL,status VARCHAR(40) NOT NULL,deadline TIMESTAMP NOT NULL,ever_overdue BOOLEAN NOT NULL DEFAULT FALSE,summarized_at TIMESTAMP NULL,accepted_at TIMESTAMP NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(host_dept_id,company_id) REFERENCES department(id,company_id),FOREIGN KEY(creator_id) REFERENCES app_user(id));
CREATE TABLE sub_task (id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,company_id BIGINT NOT NULL,dept_id BIGINT NOT NULL,owner_id BIGINT NULL,is_host BOOLEAN NOT NULL,status VARCHAR(40) NOT NULL,deadline TIMESTAMP NOT NULL,first_received_at TIMESTAMP NULL,submitted_at TIMESTAMP NULL,host_task_id BIGINT GENERATED ALWAYS AS (CASE WHEN is_host THEN task_id ELSE NULL END),UNIQUE(task_id,dept_id),UNIQUE(host_task_id),FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(dept_id,company_id) REFERENCES department(id,company_id),FOREIGN KEY(owner_id) REFERENCES app_user(id));
CREATE TABLE sub_task_assignee (sub_task_id BIGINT NOT NULL,user_id BIGINT NOT NULL,PRIMARY KEY(sub_task_id,user_id),FOREIGN KEY(sub_task_id) REFERENCES sub_task(id),FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE task_comment(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,author_id BIGINT NOT NULL,content LONGTEXT NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(author_id) REFERENCES app_user(id));
CREATE TABLE task_progress(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,sub_task_id BIGINT NOT NULL,author_id BIGINT NOT NULL,percent INT NOT NULL,note LONGTEXT NOT NULL,CHECK(percent BETWEEN 0 AND 100),FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(sub_task_id) REFERENCES sub_task(id),FOREIGN KEY(author_id) REFERENCES app_user(id));
CREATE TABLE deadline_request(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,sub_task_id BIGINT NOT NULL,requested_deadline TIMESTAMP NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(30) NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(sub_task_id) REFERENCES sub_task(id));
CREATE TABLE collaboration_request(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,dept_id BIGINT NOT NULL,company_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL,UNIQUE(task_id,dept_id),FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(dept_id,company_id) REFERENCES department(id,company_id));
CREATE TABLE result_version(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,sub_task_id BIGINT NULL,summary LONGTEXT NOT NULL,revision INT NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(sub_task_id) REFERENCES sub_task(id));
CREATE TABLE function_tag(id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,dept_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,weight INT NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(dept_id,company_id) REFERENCES department(id,company_id));
CREATE TABLE matching_rule(id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,rule_version INT NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(company_id) REFERENCES company(id));
CREATE TABLE matching_feedback(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,reason VARCHAR(1000) NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id));
CREATE TABLE notification_channel(id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,name VARCHAR(200) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(company_id) REFERENCES company(id));
CREATE TABLE kpi_template(id BIGINT PRIMARY KEY,name VARCHAR(200) NOT NULL,template_version INT NOT NULL,approved BOOLEAN NOT NULL DEFAULT FALSE,weights_json VARCHAR(200) NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id));
CREATE TABLE kpi_run(id BIGINT PRIMARY KEY,company_id BIGINT NOT NULL,period VARCHAR(7) NOT NULL,template_id BIGINT NOT NULL,simulation BOOLEAN NOT NULL,published_at TIMESTAMP NOT NULL,locked_at TIMESTAMP NULL,input_snapshot LONGTEXT NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(company_id) REFERENCES company(id),FOREIGN KEY(template_id) REFERENCES kpi_template(id));
CREATE TABLE kpi_score(id BIGINT PRIMARY KEY,run_id BIGINT NOT NULL,dept_id BIGINT NOT NULL,raw_score DECIMAL(7,2) NULL,adjusted_score DECIMAL(7,2) NULL,metrics_json LONGTEXT NOT NULL,UNIQUE(run_id,dept_id),FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(run_id) REFERENCES kpi_run(id),FOREIGN KEY(dept_id) REFERENCES department(id));
CREATE TABLE kpi_appeal(id BIGINT PRIMARY KEY,score_id BIGINT NOT NULL,applicant_id BIGINT NOT NULL,reason VARCHAR(1000) NOT NULL,decision VARCHAR(30) NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(score_id) REFERENCES kpi_score(id),FOREIGN KEY(applicant_id) REFERENCES app_user(id));
CREATE TABLE kpi_adjustment(id BIGINT PRIMARY KEY,score_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,score DECIMAL(7,2) NOT NULL,reason VARCHAR(1000) NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(score_id) REFERENCES kpi_score(id),FOREIGN KEY(actor_id) REFERENCES app_user(id));
CREATE TABLE attachment(id BIGINT PRIMARY KEY,task_id BIGINT NOT NULL,sub_task_id BIGINT NULL,uploader_id BIGINT NOT NULL,storage_key VARCHAR(100) NOT NULL UNIQUE,original_name VARCHAR(250) NOT NULL,mime_type VARCHAR(100) NOT NULL,size_bytes BIGINT NOT NULL,sha256 VARCHAR(64) NOT NULL,scan_status VARCHAR(30) NOT NULL,FOREIGN KEY(id) REFERENCES business_record(id),FOREIGN KEY(task_id) REFERENCES task(id),FOREIGN KEY(sub_task_id) REFERENCES sub_task(id),FOREIGN KEY(uploader_id) REFERENCES app_user(id));
